<?php
declare(strict_types=1);
require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';
$id=max(1,(int)($_GET['id']??$_POST['id']??0));$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);$programRepo=new QualitySystem\Repositories\ProgramSpecificationRepository($conn);$program=$programRepo->findScoped($id,$role,$user);if(!$program){http_response_code(404);exit('Program specification not found.');}$canManage=QualitySystem\Security\PermissionMatrix::allows($role,'programs','manage');
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canManage){http_response_code(403);exit('Access denied.');}$action=(string)($_POST['action']??'');if($action==='add_clo'){$course=(int)($_POST['program_course_id']??0);$code=mb_substr(trim((string)($_POST['clo_code']??'')),0,30);$domain=mb_substr(trim((string)($_POST['clo_domain']??'')),0,100);$text=trim((string)($_POST['clo_text']??''));$check=$conn->prepare('SELECT COUNT(*) FROM program_specification_courses WHERE id=:course AND program_specification_id=:program');$check->execute([':course'=>$course,':program'=>$id]);if(!$check->fetchColumn()||$code===''||$text===''){http_response_code(422);exit('Authorized course, CLO code, and CLO text are required.');}$s=$conn->prepare('INSERT INTO program_course_clos(program_specification_id,program_course_id,clo_code,clo_domain,clo_text,display_order,created_by_user_id) VALUES(:program,:course,:code,:domain,:text,(SELECT COALESCE(MAX(x.display_order),0)+1 FROM program_course_clos x WHERE x.program_course_id=:order_course),:user)');$s->execute([':program'=>$id,':course'=>$course,':code'=>$code,':domain'=>$domain?:null,':text'=>$text,':order_course'=>$course,':user'=>$user]);QualitySystem\Security\AuditLogger::record($conn,'program_clo_create','allowed','Program Specifications',[],'program_specification',$id);}elseif($action==='align'){$clo=(int)($_POST['clo_id']??0);$plo=(int)($_POST['plo_id']??0);$level=(string)($_POST['alignment_level']??'Introductory');if(!in_array($level,['Practical','Introductory','Mastery'],true))$level='Introductory';$check=$conn->prepare('SELECT (SELECT COUNT(*) FROM program_course_clos WHERE id=:clo AND program_specification_id=:program)+(SELECT COUNT(*) FROM program_specification_plos WHERE id=:plo AND program_specification_id=:program2)');$check->execute([':clo'=>$clo,':program'=>$id,':plo'=>$plo,':program2'=>$id]);if((int)$check->fetchColumn()!==2){http_response_code(422);exit('CLO and PLO must belong to this program.');}$s=$conn->prepare('INSERT INTO program_plo_clo_matrix(program_specification_id,clo_id,plo_id,alignment_level,created_by_user_id) VALUES(:program,:clo,:plo,:level,:user) ON DUPLICATE KEY UPDATE alignment_level=VALUES(alignment_level),created_by_user_id=VALUES(created_by_user_id)');$s->execute([':program'=>$id,':clo'=>$clo,':plo'=>$plo,':level'=>$level,':user'=>$user]);QualitySystem\Security\AuditLogger::record($conn,'program_plo_clo_align','allowed','Program Specifications',[],'program_specification',$id);}elseif($action==='remove_alignment'){$clo=(int)($_POST['clo_id']??0);$plo=(int)($_POST['plo_id']??0);$s=$conn->prepare('DELETE FROM program_plo_clo_matrix WHERE program_specification_id=:program AND clo_id=:clo AND plo_id=:plo');$s->execute([':program'=>$id,':clo'=>$clo,':plo'=>$plo]);}else{http_response_code(422);exit('Invalid matrix action.');}header('Location: /program_plo_clo_matrix.php?id='.$id);exit;}
$coursesStmt=$conn->prepare('SELECT pc.*,(SELECT COUNT(*) FROM program_course_clos c WHERE c.program_course_id=pc.id) clo_count FROM program_specification_courses pc WHERE pc.program_specification_id=:id ORDER BY pc.level_no,pc.course_code');$coursesStmt->execute([':id'=>$id]);$courses=$coursesStmt->fetchAll();$plosStmt=$conn->prepare('SELECT * FROM program_specification_plos WHERE program_specification_id=:id ORDER BY display_order,id');$plosStmt->execute([':id'=>$id]);$plos=$plosStmt->fetchAll();$closStmt=$conn->prepare('SELECT c.*,pc.course_code,pc.course_title FROM program_course_clos c JOIN program_specification_courses pc ON pc.id=c.program_course_id WHERE c.program_specification_id=:id ORDER BY pc.level_no,pc.course_code,c.display_order,c.id');$closStmt->execute([':id'=>$id]);$clos=$closStmt->fetchAll();$matrixStmt=$conn->prepare('SELECT * FROM program_plo_clo_matrix WHERE program_specification_id=:id');$matrixStmt->execute([':id'=>$id]);$matrix=[];foreach($matrixStmt->fetchAll()as$m)$matrix[(int)$m['clo_id']][(int)$m['plo_id']]=$m['alignment_level'];
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="program-'.$id.'-plo-clo-matrix.csv"');$out=fopen('php://output','wb');fputcsv($out,array_merge(['Course Code','Course Title','CLO Code','CLO Domain','CLO Text'],array_column($plos,'plo_code')));foreach($clos as$c){$row=[$c['course_code'],$c['course_title'],$c['clo_code'],$c['clo_domain'],$c['clo_text']];foreach($plos as$p)$row[]=$matrix[(int)$c['id']][(int)$p['id']]??'';fputcsv($out,$row);}fclose($out);exit;}
$coursesWithClos=count(array_filter($courses,fn($c)=>(int)$c['clo_count']>0));$alignedClos=count(array_filter($clos,fn($c)=>!empty($matrix[(int)$c['id']])));$readiness=count($courses)?(int)round((($coursesWithClos/count($courses))*60)+((count($clos)?$alignedClos/count($clos):0)*40)):0;$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PLO-CLO Matrix</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1500px;margin:auto;padding:1rem}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.tile{padding:1rem;background:#eef2f5;border-radius:8px}.scroll{overflow:auto}table{border-collapse:collapse;min-width:100%}th,td{border:1px solid #ccd3da;padding:.5rem;vertical-align:top}.matrix-cell{text-align:center;min-width:55px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:1rem}form.panel{padding:1rem;border:1px solid #ccd3da;border-radius:8px}label{display:block;font-weight:700}input,select,textarea{width:100%;box-sizing:border-box}.P{background:#1769d2;color:#fff}.I{background:#dbeafe}.M{background:#7c3aed;color:#fff}@media(max-width:800px){.summary,.forms{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/nav.php';?><main><p><a href="/program-specifications">← Program specifications</a></p><h1>PLO–CLO Matrix: <?=$h($program['program_name'])?></h1><div class="summary"><div class="tile"><strong><?=count($courses)?></strong><br>Program courses</div><div class="tile"><strong><?=$coursesWithClos?></strong><br>Courses with CLOs</div><div class="tile"><strong><?=count($clos)?></strong><br>CLOs entered</div><div class="tile"><strong><?=$readiness?>%</strong><br>Matrix readiness</div></div><p><a class="btn" href="?id=<?=$id?>&export=csv">Export CSV matrix</a></p><?php if(!$clos):?><p role="alert"><strong>No approved CLOs are recorded yet.</strong> Enter or import the official course CLOs before treating this matrix as academic evidence.</p><?php endif;?><?php if($canManage):?><div class="forms"><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="add_clo"><h2>Add official CLO</h2><label>Course<select name="program_course_id" required><?php foreach($courses as$c):?><option value="<?=(int)$c['id']?>"><?=$h($c['course_code'].' — '.$c['course_title'])?></option><?php endforeach;?></select></label><label>CLO code<input name="clo_code" maxlength="30" required placeholder="K1, S1, V1"></label><label>Domain<select name="clo_domain"><option>Knowledge and Understanding</option><option>Skills</option><option>Values, Autonomy, and Responsibility</option></select></label><label>Official CLO text<textarea name="clo_text" rows="4" required></textarea></label><button>Add CLO</button></form><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="align"><h2>Align CLO to PLO</h2><label>CLO<select name="clo_id" required><?php foreach($clos as$c):?><option value="<?=(int)$c['id']?>"><?=$h($c['course_code'].' '.$c['clo_code'].' — '.$c['clo_text'])?></option><?php endforeach;?></select></label><label>PLO<select name="plo_id" required><?php foreach($plos as$p):?><option value="<?=(int)$p['id']?>"><?=$h($p['plo_code'].' — '.$p['plo_text'])?></option><?php endforeach;?></select></label><label>Alignment level<select name="alignment_level"><option>Practical</option><option>Introductory</option><option>Mastery</option></select></label><button <?=$clos?'':'disabled'?>>Save alignment</button></form></div><?php endif;?><h2>Matrix</h2><div class="scroll"><table><thead><tr><th>Course</th><th>CLO</th><th>Official CLO text</th><?php foreach($plos as$p):?><th title="<?=$h($p['plo_text'])?>"><?=$h($p['plo_code'])?></th><?php endforeach;?></tr></thead><tbody><?php foreach($clos as$c):?><tr><td><?=$h($c['course_code'])?><br><?=$h($c['course_title'])?></td><td><?=$h($c['clo_code'])?><br><?=$h($c['clo_domain'])?></td><td><?=$h($c['clo_text'])?></td><?php foreach($plos as$p):$level=$matrix[(int)$c['id']][(int)$p['id']]??'';?><td class="matrix-cell <?=$level!==''?substr($level,0,1):''?>"><?=$level!==''?substr($level,0,1):''?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$clos):?><tr><td colspan="<?=3+count($plos)?>">No CLO rows available.</td></tr><?php endif;?></tbody></table></div><p><strong>Legend:</strong> P = Practical; I = Introductory; M = Mastery.</p></main></body></html>
